lines.push('// Brings total Vietnamese bank past 5000.');
lines.push('import type { VietnameseModule } from "./types";');
lines.push('');
lines.push('export const vocabularyMega3Modules: VietnameseModule[] = [');
for (const t of out) {
  lines.push('  {');
  lines.push(`    id: ${JSON.stringify(t.id)},`);
  lines.push(`    title: ${JSON.stringify(t.titleVi)},`);
  lines.push(`    titleEn: ${JSON.stringify(t.titleEn)},`);
  lines.push(`    icon: ${JSON.stringify(t.icon)},`);
  lines.push(`    color: ${JSON.stringify(t.color)},`);
  lines.push(`    description: ${JSON.stringify("Từ vựng mở rộng chủ đề " + t.titleVi.toLowerCase() + ".")},`);
  lines.push(`    descriptionEn: ${JSON.stringify("Extended vocabulary on " + t.titleEn.toLowerCase() + ".")},`);
  lines.push(`    category: "vocabulary",`);
  lines.push(`    lessons: [{`);
  lines.push(`      id: ${JSON.stringify(t.id + "-l1")},`);
  lines.push(`      title: ${JSON.stringify(t.titleVi)},`);
  lines.push(`      titleEn: ${JSON.stringify(t.titleEn)},`);
  lines.push(`      level: "advanced",`);
  lines.push(`      theory: ${JSON.stringify("Bài học mở rộng vốn từ chủ đề " + t.titleVi.toLowerCase() + " ở trình độ nâng cao.")},`);
  lines.push(`      theoryEn: ${JSON.stringify("Advanced vocabulary lesson on " + t.titleEn.toLowerCase() + ".")},`);
  lines.push(`      vocabulary: [`);
  for (const [vi, en, viM, viEx, enEx, pos] of t.entries) {
    lines.push(`        { word: ${JSON.stringify(vi)}, meaning: ${JSON.stringify(viM)}, meaningEn: ${JSON.stringify(en)}, example: ${JSON.stringify(viEx)}, exampleEn: ${JSON.stringify(enEx)}, partOfSpeech: ${JSON.stringify(pos)} },`);
  }
  lines.push(`      ],`);
  lines.push(`      quiz: [],`);
  lines.push(`    }],`);
  lines.push(`  },`);
}
lines.push('];');
lines.push('');

fs.writeFileSync('src/data/vietnamese/vocabularyMega3.ts', lines.join('\n'));
console.log(`Added ${added} new entries across ${out.length} modules (skipped ${skipped} duplicates).`);
